local WoodenColumnMaker = {}
local PRODUCTS = {
    simple_pine_column = { name = "Preprost borov steber", woodCost = 4, time = 5, cost = 90, beauty = 18, defense = 12, happiness = 1, description = "Preprost borov steber za gradnjo." },
    carved_oak_column = { name = "Izrezljan hrastov steber", woodCost = 4, leatherCost = 1, time = 8, cost = 240, beauty = 35, defense = 18, happiness = 2, prestige = 2, description = "Izrezljan hrastov steber za trgovce." },
    fluted_walnut_column = { name = "Kanelirana orehov steber", woodCost = 4, leatherCost = 1, paintCost = 1, time = 11, cost = 580, beauty = 52, defense = 24, happiness = 2, prestige = 6, description = "Kanelirana orehov steber za plemiče." },
    silver_trimmed_column = { name = "Srebrnoobrobljeni steber", woodCost = 4, silverCost = 1, leatherCost = 1, paintCost = 1, time = 15, cost = 1300, beauty = 68, defense = 30, happiness = 3, prestige = 14, description = "Srebrnoobrobljeni steber za visoke plemiče." },
    gold_inlaid_column = { name = "Zlatovloženi steber", woodCost = 4, goldCost = 1, silverCost = 1, leatherCost = 1, paintCost = 1, jewelCost = 1, time = 19, cost = 2900, beauty = 82, defense = 38, happiness = 5, prestige = 27, description = "Zlatovloženi steber z draguljem za visoko plemstvo." },
    royal_grand_column = { name = "Kraljevski veliki steber", woodCost = 6, goldCost = 2, silverCost = 2, leatherCost = 1, paintCost = 1, jewelCost = 2, pearlCost = 2, time = 26, cost = 6200, beauty = 95, defense = 50, happiness = 12, prestige = 58, description = "Veliki kraljevski steber z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    column_workshop = { name = "Stebrična delavnica", cost = { gold = 260, wood = 180, stone = 100 }, upkeep = 6, qualityBonus = 5 },
    woodwork_loft = { name = "Lesna podstrešje", cost = { gold = 950, wood = 320, stone = 220, silver = 6 }, upkeep = 22, qualityBonus = 18 },
    master_column_atelier = { name = "Mojstrski stebrični atelje", cost = { gold = 2700, wood = 380, stone = 480, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_column_palace = { name = "Kraljevska stebrična palača", cost = { gold = 11500, wood = 600, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
WoodenColumnMaker.woodStock = 22; WoodenColumnMaker.leatherStock = 10; WoodenColumnMaker.paintStock = 10; WoodenColumnMaker.silverStock = 6; WoodenColumnMaker.goldStock = 6; WoodenColumnMaker.jewelStock = 4; WoodenColumnMaker.pearlStock = 4
WoodenColumnMaker.productStock = {}; WoodenColumnMaker.buildings = {}; WoodenColumnMaker.maker = nil; WoodenColumnMaker.activeMaking = {}; WoodenColumnMaker.totalProducts = 0; WoodenColumnMaker.dayTimer = 0
function WoodenColumnMaker.init() WoodenColumnMaker.woodStock=22; WoodenColumnMaker.leatherStock=10; WoodenColumnMaker.paintStock=10; WoodenColumnMaker.silverStock=6; WoodenColumnMaker.goldStock=6; WoodenColumnMaker.jewelStock=4; WoodenColumnMaker.pearlStock=4; WoodenColumnMaker.productStock={}; WoodenColumnMaker.buildings={}; WoodenColumnMaker.maker=nil; WoodenColumnMaker.activeMaking={}; WoodenColumnMaker.totalProducts=0; WoodenColumnMaker.dayTimer=0; print("[WoodenColumnMaker] Royal Wooden Column Maker System initialized (6 products, 4 buildings)") end
function WoodenColumnMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WoodenColumnMaker.maker={name=n or ("Stebričar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stebričar najet: %s (spretnost: %d)",WoodenColumnMaker.maker.name,s),"success") end; return true end
function WoodenColumnMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WoodenColumnMaker.build(id) local ok,e=WoodenColumnMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WoodenColumnMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WoodenColumnMaker.getQualityBonus() local b=0; for _,bd in ipairs(WoodenColumnMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WoodenColumnMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and WoodenColumnMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WoodenColumnMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.paintCost and WoodenColumnMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and WoodenColumnMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WoodenColumnMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WoodenColumnMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WoodenColumnMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WoodenColumnMaker.buildings==0 then return false,"Potrebna stebrična delavnica" end; if not WoodenColumnMaker.maker then return false,"Potreben stebričar" end; return true end
function WoodenColumnMaker.make(pt,qty) qty=qty or 1; local ok,e=WoodenColumnMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then WoodenColumnMaker.woodStock=WoodenColumnMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WoodenColumnMaker.leatherStock=WoodenColumnMaker.leatherStock-d.leatherCost*qty end; if d.paintCost then WoodenColumnMaker.paintStock=WoodenColumnMaker.paintStock-d.paintCost*qty end; if d.silverCost then WoodenColumnMaker.silverStock=WoodenColumnMaker.silverStock-d.silverCost*qty end; if d.goldCost then WoodenColumnMaker.goldStock=WoodenColumnMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WoodenColumnMaker.jewelStock=WoodenColumnMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WoodenColumnMaker.pearlStock=WoodenColumnMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WoodenColumnMaker.maker then t=math.max(1,t-math.floor(WoodenColumnMaker.maker.skill/12)) end; table.insert(WoodenColumnMaker.activeMaking,{id="column_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Rezbarjenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WoodenColumnMaker.completeMaking(m) local q=1.0+(WoodenColumnMaker.getQualityBonus()/100); if WoodenColumnMaker.maker then q=q+(WoodenColumnMaker.maker.skill/140) end; q=math.min(2.5,q); WoodenColumnMaker.productStock[m.productType]=(WoodenColumnMaker.productStock[m.productType] or 0)+m.quantity; WoodenColumnMaker.totalProducts=WoodenColumnMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WoodenColumnMaker.maker then WoodenColumnMaker.maker.itemsMade=WoodenColumnMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WoodenColumnMaker.maker.skill=math.min(100,WoodenColumnMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steber izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"column.completed",{productName=m.productName,beauty=m.beauty,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function WoodenColumnMaker.update(dt) if not _G.state then return end; WoodenColumnMaker.dayTimer=WoodenColumnMaker.dayTimer+dt; if WoodenColumnMaker.dayTimer>=30 then WoodenColumnMaker.dayTimer=0; for i=#WoodenColumnMaker.activeMaking,1,-1 do local m=WoodenColumnMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WoodenColumnMaker.completeMaking(m); table.remove(WoodenColumnMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WoodenColumnMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WoodenColumnMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WoodenColumnMaker.getStats() return {woodStock=WoodenColumnMaker.woodStock,leatherStock=WoodenColumnMaker.leatherStock,paintStock=WoodenColumnMaker.paintStock,silverStock=WoodenColumnMaker.silverStock,goldStock=WoodenColumnMaker.goldStock,jewelStock=WoodenColumnMaker.jewelStock,pearlStock=WoodenColumnMaker.pearlStock,productStock=WoodenColumnMaker.productStock,numBuildings=#WoodenColumnMaker.buildings,hasMaker=WoodenColumnMaker.maker~=nil,makerName=WoodenColumnMaker.maker and WoodenColumnMaker.maker.name or "—",makerSkill=WoodenColumnMaker.maker and WoodenColumnMaker.maker.skill or 0,activeMaking=#WoodenColumnMaker.activeMaking,totalProducts=WoodenColumnMaker.totalProducts} end
return WoodenColumnMaker
